#!/usr/bin/env python3
"""
Round 110c (tiles), 29 September 2026. Replaces 109c/109d (never uploaded).

scripts/capture.py (weekly, or by hand: capture) and scripts/capture_ipn.py
(daily until IPN's catalogue is read, or by hand: capture_ipn), for the
culprits row capture_cases. capture/cases.geojson (the compiled cases) is
written only if there is none yet, so the row draws before the first run.
"""
import base64, pathlib

FILES = {'scripts/capture.py': '', 'scripts/capture_ipn.py': ''}
SEED = ("capture/cases.geojson", '')


def main():
    for p, b in FILES.items():
        data = base64.b64decode(b)
        f = pathlib.Path(p)
        if f.exists() and f.read_bytes() == data:
            print(f"round110c: {p} already up to date")
            continue
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_bytes(data)
        print(f"round110c: wrote {p}")
    f = pathlib.Path(SEED[0])
    if f.exists():
        print(f"round110c: {SEED[0]} exists; left as built")
    else:
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_bytes(base64.b64decode(SEED[1]))
        print(f"round110c: wrote {SEED[0]}")


if __name__ == "__main__":
    main()
